import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
from pathlib import Path


# ============================================================
# Configuration
# ============================================================

# Name of the CSV file generated by the controller.
# Place this Python file in the same folder as the CSV file,
# or replace the path below with the full path to your CSV file.
csv_file = "impedance_experiment_log.csv"

# Folder where the generated figures will be saved.
output_folder = Path("evaluation_plots")
output_folder.mkdir(exist_ok=True)


# ============================================================
# Load CSV log file
# ============================================================

data = pd.read_csv(csv_file)


# ============================================================
# Compute error norms
# ============================================================

data["e_p_norm"] = np.sqrt(
    data["e_p_x"]**2 +
    data["e_p_y"]**2 +
    data["e_p_z"]**2
)

data["e_R_norm"] = np.sqrt(
    data["e_R_x"]**2 +
    data["e_R_y"]**2 +
    data["e_R_z"]**2
)


# ============================================================
# Evaluation functions
# ============================================================

def steady_state_error(error_norm, percentage=0.2):
    """
    Compute the mean error over the final part of the experiment.
    By default, the final 20% of the experiment is used.
    """
    start_index = int((1.0 - percentage) * len(error_norm))
    return np.mean(error_norm[start_index:])


def maximum_error(error_norm):
    """
    Compute the maximum value of an error norm.
    """
    return np.max(error_norm)


def compute_overshoot(error_component):
    """
    Compute overshoot after the first zero crossing of one error component.
    If the component does not cross zero, the overshoot is set to zero.
    """
    error_component = np.asarray(error_component)

    zero_crossings = np.where(np.diff(np.sign(error_component)) != 0)[0]

    if len(zero_crossings) == 0:
        return 0.0

    first_crossing = zero_crossings[0]
    return np.max(np.abs(error_component[first_crossing:]))


# ============================================================
# Numerical evaluation
# ============================================================

e_p_max = maximum_error(data["e_p_norm"])
e_R_max = maximum_error(data["e_R_norm"])

e_p_ss = steady_state_error(data["e_p_norm"])
e_R_ss = steady_state_error(data["e_R_norm"])

overshoot_ep_x = compute_overshoot(data["e_p_x"])
overshoot_ep_y = compute_overshoot(data["e_p_y"])
overshoot_ep_z = compute_overshoot(data["e_p_z"])

overshoot_eR_x = compute_overshoot(data["e_R_x"])
overshoot_eR_y = compute_overshoot(data["e_R_y"])
overshoot_eR_z = compute_overshoot(data["e_R_z"])

tau_max = {}
for i in range(1, 8):
    column = f"tau_{i}"
    if column in data.columns:
        tau_max[column] = data[column].abs().max()


# ============================================================
# Print evaluation results
# ============================================================

print("Evaluation Results")
print("------------------")
print(f"Maximum positional error:      {e_p_max:.6f} m")
print(f"Steady-state positional error: {e_p_ss:.6f} m")
print()
print(f"Maximum rotational error:      {e_R_max:.6f} rad")
print(f"Steady-state rotational error: {e_R_ss:.6f} rad")
print()
print("Position overshoot:")
print(f"  e_p_x overshoot: {overshoot_ep_x:.6f} m")
print(f"  e_p_y overshoot: {overshoot_ep_y:.6f} m")
print(f"  e_p_z overshoot: {overshoot_ep_z:.6f} m")
print()
print("Rotational overshoot:")
print(f"  e_R_x overshoot: {overshoot_eR_x:.6f} rad")
print(f"  e_R_y overshoot: {overshoot_eR_y:.6f} rad")
print(f"  e_R_z overshoot: {overshoot_eR_z:.6f} rad")
print()
print("Maximum commanded joint torques:")
for key, value in tau_max.items():
    print(f"  {key}: {value:.6f} Nm")


# ============================================================
# Plot 1: measured and desired position
# ============================================================

plt.figure(figsize=(8, 4.5))
plt.plot(data["time"], data["p_d_x"], label=r"$p_{d,x}$")
plt.plot(data["time"], data["p_EE_x"], "--", label=r"$p_{\mathrm{EE},x}$")
plt.plot(data["time"], data["p_d_y"], label=r"$p_{d,y}$")
plt.plot(data["time"], data["p_EE_y"], "--", label=r"$p_{\mathrm{EE},y}$")
plt.plot(data["time"], data["p_d_z"], label=r"$p_{d,z}$")
plt.plot(data["time"], data["p_EE_z"], "--", label=r"$p_{\mathrm{EE},z}$")
plt.xlabel("Time [s]")
plt.ylabel("Position [m]")
plt.title("Desired and Measured End-Effector Position")
plt.legend(ncol=2)
plt.grid(True)
plt.tight_layout()
plt.savefig(output_folder / "desired_measured_position.png", dpi=200)
plt.show()


