# ============================================================

plt.figure(figsize=(8, 4.5))
for i in range(1, 8):
    column = f"tau_{i}"
    if column in data.columns:
        plt.plot(data["time"], data[column], label=rf"$\tau_{i}$")

plt.xlabel("Time [s]")
plt.ylabel("Joint torque [Nm]")
