# ============================================================
# Plot 9: compliance displacement
# ============================================================
# This plot is useful for compliance experiments.
# The maximum value of ||e_p|| corresponds to the maximum displacement
# from the desired pose during manual interaction.

plt.figure(figsize=(8, 4.5))
plt.plot(data["time"], data["e_p_norm"], label=r"$\Delta p(t)=\|e_p(t)\|$")
plt.xlabel("Time [s]")
plt.ylabel("Displacement from desired pose [m]")
plt.title("Compliance Evaluation: End-Effector Displacement")
plt.legend()
plt.grid(True)
plt.tight_layout()
plt.savefig(output_folder / "compliance_displacement.png", dpi=200)
plt.show()


print()
print(f"Figures saved in folder: {output_folder.resolve()}")
